int ip_options_get(struct net *net, struct ip_options_rcu **optp,
		   sockptr_t data, int optlen)
{
	struct ip_options_rcu *opt;

	opt = kzalloc(sizeof(struct ip_options_rcu) + ((optlen + 3) & ~3),
		       GFP_KERNEL);
	if (!opt)
		return -ENOMEM;
	if (optlen && copy_from_sockptr(opt->opt.__data, data, optlen)) {
		kfree(opt);
		return -EFAULT;
	}

	while (optlen & 3)
		opt->opt.__data[optlen++] = IPOPT_END;
	opt->opt.optlen = optlen;
	if (optlen && ip_options_compile(net, &opt->opt, NULL)) {
		kfree(opt);
		return -EINVAL;
	}
	kfree(*optp);
	*optp = opt;
	return 0;
}

int ip_options_get(struct net *net, struct ip_options_rcu **optp,
		   sockptr_t data, int optlen)
{
	struct ip_options_rcu *opt;

	opt = kzalloc(sizeof(struct ip_options_rcu) + ((optlen + 3) & ~3),
		       GFP_KERNEL);
	if (!opt)
		return -ENOMEM;
	if (optlen && copy_from_sockptr(opt->opt.__data, data, optlen)) {
		kfree(opt);
		return -EFAULT;
	}

	while (optlen & 3)
		opt->opt.__data[optlen++] = IPOPT_END;
	opt->opt.optlen = optlen;
	if (optlen && ip_options_compile(net, &opt->opt, NULL)) {
		kfree(opt);
		return -EINVAL;
	}
	if (opt->opt.srr && !ns_capable(net->user_ns, CAP_NET_RAW)) {
		kfree(opt);
		return -EPERM;
	}
	kfree(*optp);
	*optp = opt;
	return 0;
}

static __kernel_ulong_t damos_get_node_mem_bp(
		struct damos_quota_goal *goal)
{
	struct sysinfo i;
	__kernel_ulong_t numerator;

	si_meminfo_node(&i, goal->nid);
	if (goal->metric == DAMOS_QUOTA_NODE_MEM_USED_BP)
		numerator = i.totalram - i.freeram;
	else	
		numerator = i.freeram;
	return mult_frac(numerator, 10000, i.totalram);
}

static __kernel_ulong_t damos_get_node_mem_bp(
		struct damos_quota_goal *goal)
{
	struct sysinfo i;
	__kernel_ulong_t numerator;

	if (invalid_mem_node(goal->nid)) {
		if (goal->metric == DAMOS_QUOTA_NODE_MEM_USED_BP)
			return 0;
		else	
			return 10000;
	}

	si_meminfo_node(&i, goal->nid);
	if (goal->metric == DAMOS_QUOTA_NODE_MEM_USED_BP)
		numerator = i.totalram - i.freeram;
	else	
		numerator = i.freeram;
	return mult_frac(numerator, 10000, i.totalram);
}

static int vfio_cdx_set_msi_trigger(struct vfio_cdx_device *vdev,
				    unsigned int index, unsigned int start,
				    unsigned int count, u32 flags,
				    void *data)
{
	struct cdx_device *cdx_dev = to_cdx_device(vdev->vdev.dev);
	int i;

	if (start + count > cdx_dev->num_msi)
		return -EINVAL;

	if (!count && (flags & VFIO_IRQ_SET_DATA_NONE)) {
		vfio_cdx_msi_disable(vdev);
		return 0;
	}

	if (flags & VFIO_IRQ_SET_DATA_EVENTFD) {
		s32 *fds = data;
		int ret;

		if (vdev->config_msi)
			return vfio_cdx_msi_set_block(vdev, start, count,
						  fds);
		ret = vfio_cdx_msi_enable(vdev, cdx_dev->num_msi);
		if (ret)
			return ret;

		ret = vfio_cdx_msi_set_block(vdev, start, count, fds);
		if (ret)
			vfio_cdx_msi_disable(vdev);

		return ret;
	}

	for (i = start; i < start + count; i++) {
		if (!vdev->cdx_irqs[i].trigger)
			continue;
		if (flags & VFIO_IRQ_SET_DATA_NONE) {
			eventfd_signal(vdev->cdx_irqs[i].trigger);
		} else if (flags & VFIO_IRQ_SET_DATA_BOOL) {
			u8 *bools = data;

			if (bools[i - start])
				eventfd_signal(vdev->cdx_irqs[i].trigger);
		}
	}

	return 0;
}

