				      unsigned flags)
{
	bool write64bit = flags & AMDGPU_FENCE_FLAG_64BIT;

	amdgpu_ring_write(ring, SDMA_PKT_HEADER_OP(SDMA_OP_FENCE));

	WARN_ON(addr & 0x3);
	amdgpu_ring_write(ring, lower_32_bits(addr));
