	r = ttm_bo_validate(&bo->tbo, &placement, &ctx);
	if (r) {
		DRM_ERROR("Failed to invalidate DMA-buf import (%d))\n", r);
		return;
	}

	for (bo_base = bo->vm_bo; bo_base; bo_base = bo_base->next) {
		struct amdgpu_vm *vm = bo_base->vm;
		struct dma_resv *resv = vm->root.bo->tbo.base.resv;

		if (ticket) {




			r = dma_resv_lock(resv, ticket);
			if (r)
				continue;

		} else {




			if (!dma_resv_trylock(resv))
				continue;
		}


		r = dma_resv_reserve_fences(resv, 2);
		if (!r)
			r = amdgpu_vm_clear_freed(adev, vm, NULL);







		if (!r)
			r = amdgpu_vm_handle_moved(adev, vm, NULL);

		if (r && r != -EBUSY)
			DRM_ERROR("Failed to invalidate VM page tables (%d))\n",
				  r);

		dma_resv_unlock(resv);
	}
}

static u64 dma_length(struct ethosu_validated_cmdstream_info *info,
		      struct dma_state *dma_st, struct dma *dma)
{
	s8 mode = dma_st->mode;
	u64 len = dma->len;

	if (mode >= 1) {
		if (dma->stride[0] < 0 && (u64)(-dma->stride[0]) > len)
			return U64_MAX;
		len += dma->stride[0];
		if (check_mul_overflow(len, (u64)dma_st->size0, &len))
			return U64_MAX;
	}
	if (mode == 2) {
		if (dma->stride[1] < 0 && (u64)(-dma->stride[1]) > len)
			return U64_MAX;
		len += dma->stride[1];
		if (check_mul_overflow(len, (u64)dma_st->size1, &len))
			return U64_MAX;
	}
	if (dma->region >= 0) {
		u64 end;

		if (check_add_overflow(len, dma->offset, &end))
			return U64_MAX;
		info->region_size[dma->region] = max(info->region_size[dma->region], end);
	}

	return len;
}

