	if (IS_ENABLED(CONFIG_PREEMPT_RT) && (in_nmi() || in_hardirq()))
		return NULL;


	if (!IS_ENABLED(CONFIG_SMP) && in_nmi())
		return NULL;

retry:
	if (unlikely(size > KMALLOC_MAX_CACHE_SIZE))
		return NULL;
	s = kmalloc_slab(size, NULL, alloc_gfp, _RET_IP_);

	if (!(s->flags & __CMPXCHG_DOUBLE) && !kmem_cache_debug(s))









		return NULL;

	ret = alloc_from_pcs(s, alloc_gfp, node);
	if (ret)
		goto success;







	ret = __slab_alloc_node(s, alloc_gfp, node, _RET_IP_, size);







	if (!ret && can_retry) {

		size = s->object_size + 1;






		can_retry = false;
		goto retry;
	}

success:
	maybe_wipe_obj_freeptr(s, ret);
	slab_post_alloc_hook(s, NULL, alloc_gfp, 1, &ret,
			     slab_want_init_on_alloc(alloc_gfp, s), size);

	ret = kasan_kmalloc(s, ret, size, alloc_gfp);
	return ret;
}

int ncsi_aen_handler(struct ncsi_dev_priv *ndp, struct sk_buff *skb)
{
	struct ncsi_aen_pkt_hdr *h;
	struct ncsi_aen_handler *nah = NULL;
	int i, ret;


	h = (struct ncsi_aen_pkt_hdr *)skb_network_header(skb);
	for (i = 0; i < ARRAY_SIZE(ncsi_aen_handlers); i++) {
		if (ncsi_aen_handlers[i].type == h->type) {
			nah = &ncsi_aen_handlers[i];
			break;
		}
	}

	if (!nah) {
		netdev_warn(ndp->ndev.dev, "Invalid AEN (0x%x) received\n",
			    h->type);
		return -ENOENT;
	}

	ret = ncsi_validate_aen_pkt(h, nah->payload);
	if (ret) {
		netdev_warn(ndp->ndev.dev,
			    "NCSI: 'bad' packet ignored for AEN type 0x%x\n",
			    h->type);
		goto out;
	}

	ret = nah->handler(ndp, h);
	if (ret)
		netdev_err(ndp->ndev.dev,
			   "NCSI: Handler for AEN type 0x%x returned %d\n",
			   h->type, ret);
out:
	consume_skb(skb);
	return ret;
}

