int rtw_get_wapi_ie(u8 *in_ie, uint in_len, u8 *wapi_ie, u16 *wapi_len)
{
	int len = 0;
	u8 authmode;
	uint	cnt;
	u8 wapi_oui1[4] = {0x0, 0x14, 0x72, 0x01};
	u8 wapi_oui2[4] = {0x0, 0x14, 0x72, 0x02};

	if (wapi_len)
		*wapi_len = 0;

	if (!in_ie || in_len <= 0)
		return len;

	cnt = (_TIMESTAMP_ + _BEACON_ITERVAL_ + _CAPABILITY_);

	while (cnt < in_len) {
		authmode = in_ie[cnt];

		if (authmode == WLAN_EID_BSS_AC_ACCESS_DELAY &&
		    (!memcmp(&in_ie[cnt + 6], wapi_oui1, 4) ||
		     !memcmp(&in_ie[cnt + 6], wapi_oui2, 4))) {
			if (wapi_ie)
				memcpy(wapi_ie, &in_ie[cnt], in_ie[cnt + 1] + 2);

			if (wapi_len)
				*wapi_len = in_ie[cnt + 1] + 2;
		}

		cnt += in_ie[cnt + 1] + 2;   
	}

	if (wapi_len)
		len = *wapi_len;

	return len;
}

int rtw_get_wapi_ie(u8 *in_ie, uint in_len, u8 *wapi_ie, u16 *wapi_len)
{
	int len = 0;
	u8 authmode;
	uint	cnt;
	u8 wapi_oui1[4] = {0x0, 0x14, 0x72, 0x01};
	u8 wapi_oui2[4] = {0x0, 0x14, 0x72, 0x02};

	if (wapi_len)
		*wapi_len = 0;

	if (!in_ie || in_len <= 0)
		return len;

	cnt = (_TIMESTAMP_ + _BEACON_ITERVAL_ + _CAPABILITY_);

	while (cnt < in_len) {
		if (cnt + 2 > in_len)
			break;
		if (cnt + 2 + in_ie[cnt + 1] > in_len)
			break;
		authmode = in_ie[cnt];

		if (authmode == WLAN_EID_BSS_AC_ACCESS_DELAY &&
		    in_ie[cnt + 1] >= 8 &&
		    (!memcmp(&in_ie[cnt + 6], wapi_oui1, 4) ||
		     !memcmp(&in_ie[cnt + 6], wapi_oui2, 4))) {
			if (wapi_ie)
				memcpy(wapi_ie, &in_ie[cnt], in_ie[cnt + 1] + 2);

			if (wapi_len)
				*wapi_len = in_ie[cnt + 1] + 2;
		}

		cnt += in_ie[cnt + 1] + 2;   
	}

	if (wapi_len)
		len = *wapi_len;

	return len;
}

static int epaddr_len(const struct nf_conn *ct, const char *dptr,
		      const char *limit, int *shift)
{
	union nf_inet_addr addr;
	const char *aux = dptr;

	if (!sip_parse_addr(ct, dptr, &dptr, &addr, limit, true)) {
		pr_debug("ip: %s parse failed.!\n", dptr);
		return 0;
	}


	if (*dptr == ':') {
		dptr++;
		dptr += digits_len(ct, dptr, limit, shift);
	}
	return dptr - aux;
}

static int epaddr_len(const struct nf_conn *ct, const char *dptr,
		      const char *limit, int *shift)
{
	union nf_inet_addr addr;
	const char *aux = dptr;

	if (!sip_parse_addr(ct, dptr, &dptr, &addr, limit, true)) {
		pr_debug("ip: %s parse failed.!\n", dptr);
		return 0;
	}

	if (!sip_parse_port(dptr, &dptr, limit, NULL))
		return 0;
	return dptr - aux;
}

static ssize_t driver_override_store(struct device *dev,
				     struct device_attribute *attr,
				     const char *buf, size_t count)
{
	struct ap_queue *aq = to_ap_queue(dev);
	struct ap_device *ap_dev = &aq->ap_dev;
	int rc = -EINVAL;
	bool old_value;

	if (mutex_lock_interruptible(&ap_attr_mutex))
		return -ERESTARTSYS;


	if (ap_apmask_aqmask_in_use)
		goto out;

	old_value = ap_dev->driver_override ? true : false;
	rc = driver_set_override(dev, &ap_dev->driver_override, buf, count);
	if (rc)
		goto out;
	if (old_value && !ap_dev->driver_override)
		--ap_driver_override_ctr;
	else if (!old_value && ap_dev->driver_override)
		++ap_driver_override_ctr;

	rc = count;

out:
	mutex_unlock(&ap_attr_mutex);
	return rc;
}

static ssize_t driver_override_store(struct device *dev,
				     struct device_attribute *attr,
				     const char *buf, size_t count)
{
	int rc = -EINVAL;
	bool old_value;

	if (mutex_lock_interruptible(&ap_attr_mutex))
		return -ERESTARTSYS;


	if (ap_apmask_aqmask_in_use)
		goto out;

	old_value = device_has_driver_override(dev);
	rc = __device_set_driver_override(dev, buf, count);
	if (rc)
		goto out;
	if (old_value && !device_has_driver_override(dev))
		--ap_driver_override_ctr;
	else if (!old_value && device_has_driver_override(dev))
		++ap_driver_override_ctr;

	rc = count;

out:
	mutex_unlock(&ap_attr_mutex);
	return rc;
}

static uint32_t *get_queue_ids(uint32_t num_queues, uint32_t *usr_queue_id_array)
{
	if (!usr_queue_id_array)
		return NULL;

	if (num_queues > KFD_MAX_NUM_OF_QUEUES_PER_PROCESS)
		return ERR_PTR(-EINVAL);

	return memdup_user(usr_queue_id_array,
			   array_size(num_queues, sizeof(uint32_t)));
}

